{
  "items": [
    {
      "name": "MvPolynomial.support_sum_monomial_coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R),\n  ∑ v ∈ p.support, (MvPolynomial.monomial v) (MvPolynomial.coeff v p) = p"
    },
    {
      "name": "MvPolynomial.as_sum",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R),\n  p = ∑ v ∈ p.support, (MvPolynomial.monomial v) (MvPolynomial.coeff v p)"
    },
    {
      "name": "Polynomial.sum_monomial_eq",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), (p.sum fun n a => (Polynomial.monomial n) a) = p"
    },
    {
      "name": "MvPolynomial.sum_def",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {A : Type u_2} [inst_1 : AddCommMonoid A] {p : MvPolynomial σ R}\n  {b : (σ →₀ ℕ) → R → A}, Finsupp.sum p b = ∑ m ∈ p.support, b m (MvPolynomial.coeff m p)"
    },
    {
      "name": "MvPolynomial.eval_eq'",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : Fintype σ] (X : σ → R) (f : MvPolynomial σ R),\n  (MvPolynomial.eval X) f = ∑ d ∈ f.support, MvPolynomial.coeff d f * ∏ i, X i ^ d i"
    },
    {
      "name": "MvPolynomial.sum_monomial_eq",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {A : Type u_2} [inst_1 : AddCommMonoid A] {u : σ →₀ ℕ} {r : R}\n  {b : (σ →₀ ℕ) → R → A}, b u 0 = 0 → Finsupp.sum ((MvPolynomial.monomial u) r) b = b u r"
    },
    {
      "name": "Polynomial.as_sum_support",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), p = ∑ i ∈ p.support, (Polynomial.monomial i) (p.coeff i)"
    },
    {
      "name": "Polynomial.as_sum_range",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R),\n  p = ∑ i ∈ Finset.range (p.natDegree + 1), (Polynomial.monomial i) (p.coeff i)"
    }
  ]
}
